<template>
  <div><div class="toolbar page-toolbar"><strong class="cell-primary">{{ detail?.course.code || detail?.course.title || 'Chi tiết khóa học' }}</strong><div class="toolbar-actions"><button v-if="canManage && detail && isCourseDraft(detail.course.status)" class="button primary" @click="publishCourse">Phát hành khóa học</button><button v-if="canManage && detail && isCoursePublished(detail.course.status)" class="button secondary" @click="archiveCourse">Lưu trữ khóa học</button><button v-if="canManage && detail" class="button primary" @click="showForm = !showForm">{{ showForm ? 'Đóng biểu mẫu' : 'Thêm nội dung' }}</button><RouterLink class="button secondary" to="/courses">Quay lại</RouterLink></div></div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><section v-if="showForm && detail" class="panel" style="margin-bottom:16px"><form class="inline-form" @submit.prevent="createModule"><div class="form-field"><label>Tên mô-đun</label><input v-model.trim="moduleForm.title" class="form-input" required /></div><div class="form-field" style="max-width:110px"><label>Thứ tự</label><input v-model.number="moduleForm.order" class="form-input" type="number" min="0" required /></div><button class="button primary">Tạo mô-đun</button></form><form v-if="detail.modules.length" class="inline-form" style="margin-top:12px" @submit.prevent="createLesson"><div class="form-field"><label>Mô-đun</label><select v-model="lessonForm.moduleId" class="form-select" required><option value="">Chọn mô-đun</option><option v-for="module in detail.modules" :key="module.id" :value="module.id">{{ module.title }}</option></select></div><div class="form-field"><label>Tên bài học</label><input v-model.trim="lessonForm.title" class="form-input" required /></div><div class="form-field"><label>Tóm tắt</label><input v-model.trim="lessonForm.summary" class="form-input" /></div><button class="button secondary">Tạo bài học</button></form></section><div v-if="loading" class="loading-state">Đang tải khóa học…</div><div v-else-if="detail" class="grid-two"><section class="panel"><div class="panel-heading"><h2>Mô-đun và bài học</h2><span>{{ detail.lessons.length }} bài học</span></div><div v-if="detail.modules.length" class="list-compact"><div v-for="module in detail.modules" :key="module.id" class="list-compact-item"><div><strong>{{ module.order }}. {{ module.title }}</strong><span>{{ lessonsFor(module.id).length }} bài học · {{ enumLabel(module.status, enumLabels.academicContentStatus) }}</span></div><div class="card-actions"><StatusPill :value="module.status" :labels="enumLabels.academicContentStatus" /><button v-if="canManage && isContentDraft(module.status)" class="mini-button" @click="publishModule(module.id)">Công bố</button><button v-else-if="canManage && isContentPublished(module.status)" class="mini-button" @click="archiveModule(module.id)">Lưu trữ</button></div></div></div><div v-else class="empty-state"><strong>Chưa có mô-đun</strong><span>Nội dung khóa học sẽ được bổ sung tại đây.</span></div></section><section class="panel"><div class="panel-heading"><h2>Danh sách bài học</h2><span>{{ detail.lessons.length }}</span></div><div v-if="detail.lessons.length" class="list-compact"><div v-for="lesson in detail.lessons" :key="lesson.id" class="list-compact-item"><div><strong>{{ lesson.order }}. {{ lesson.title }}</strong><span>{{ lesson.contentSummary || 'Chưa có tóm tắt' }} · {{ moduleTitle(lesson.courseModuleId) }}</span></div><div class="card-actions"><StatusPill :value="lesson.status" :labels="enumLabels.academicContentStatus" /><button v-if="canManage && isContentDraft(lesson.status)" class="mini-button" @click="publishLesson(lesson)">Công bố</button><button v-else-if="canManage && isContentPublished(lesson.status)" class="mini-button" @click="archiveLesson(lesson)">Lưu trữ</button></div></div></div><div v-else class="empty-state"><strong>Chưa có bài học</strong><span>Hãy tạo mô-đun và bài học từ giao diện quản trị.</span></div></section></div></div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute } from 'vue-router'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import { academicsApi } from '../../../shared/api/client'; import { errorMessage } from '../../../shared/api/http'; import { enumLabels, enumLabel, type CourseDetail } from '../../../shared/types'; import { useNavigationStore } from '../../../shared/stores/navigation'; import { useAuthStore } from '../../../shared/stores/auth'
const route = useRoute(); const navigation = useNavigationStore(); const auth = useAuthStore(); const detail = ref<CourseDetail | null>(null); const loading = ref(true); const error = ref(''); const showForm = ref(false); const canManage = computed(() => auth.has('academics.courses.manage')); const moduleForm = reactive({ title: '', order: 0 }); const lessonForm = reactive({ moduleId: '', title: '', summary: '' }); function lessonsFor(moduleId: string) { return detail.value?.lessons.filter(item => item.courseModuleId === moduleId) || [] } function moduleTitle(moduleId: string) { return detail.value?.modules.find(item => item.id === moduleId)?.title || 'Mô-đun' } function isCourseDraft(status: string | number) { return status === 0 || String(status).toLowerCase() === 'draft' } function isCoursePublished(status: string | number) { return status === 1 || String(status).toLowerCase() === 'published' } function isContentDraft(status: string | number) { return status === 0 || String(status).toLowerCase() === 'draft' } function isContentPublished(status: string | number) { return status === 1 || String(status).toLowerCase() === 'published' }
async function load() { loading.value = true; try { detail.value = await academicsApi.course(String(route.params.courseId)); navigation.renameTab(route.fullPath, detail.value.course.code || detail.value.course.title) } catch (cause) { error.value = errorMessage(cause) || 'Không tải được khóa học.' } finally { loading.value = false } } async function publishCourse() { if (!detail.value) return; try { detail.value.course = await academicsApi.publishCourse(detail.value.course.id); await load() } catch (cause) { error.value = errorMessage(cause) || 'Không phát hành được khóa học.' } } async function archiveCourse() { if (!detail.value || !window.confirm('Lưu trữ khóa học này?')) return; try { detail.value.course = await academicsApi.archiveCourse(detail.value.course.id); await load() } catch (cause) { error.value = errorMessage(cause) || 'Không lưu trữ được khóa học.' } } async function publishModule(moduleId: string) { if (!detail.value) return; try { await academicsApi.publishModule(detail.value.course.id, moduleId); await load() } catch (cause) { error.value = errorMessage(cause) || 'Không công bố được mô-đun.' } } async function archiveModule(moduleId: string) { if (!detail.value || !window.confirm('Lưu trữ mô-đun và các bài học bên trong?')) return; try { await academicsApi.archiveModule(detail.value.course.id, moduleId); await load() } catch (cause) { error.value = errorMessage(cause) || 'Không lưu trữ được mô-đun.' } } async function publishLesson(lesson: { id: string; courseModuleId: string }) { if (!detail.value) return; try { await academicsApi.publishLesson(detail.value.course.id, lesson.courseModuleId, lesson.id); await load() } catch (cause) { error.value = errorMessage(cause) || 'Không công bố được bài học.' } } async function archiveLesson(lesson: { id: string; courseModuleId: string }) { if (!detail.value || !window.confirm('Lưu trữ bài học này?')) return; try { await academicsApi.archiveLesson(detail.value.course.id, lesson.courseModuleId, lesson.id); await load() } catch (cause) { error.value = errorMessage(cause) || 'Không lưu trữ được bài học.' } } async function createModule() { if (!detail.value) return; try { await academicsApi.createModule(detail.value.course.id, moduleForm); moduleForm.title = ''; moduleForm.order++; await load() } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được mô-đun.' } } async function createLesson() { if (!detail.value || !lessonForm.moduleId) return; try { await academicsApi.createLesson(detail.value.course.id, lessonForm.moduleId, { title: lessonForm.title, order: lessonsFor(lessonForm.moduleId).length, contentSummary: lessonForm.summary }); lessonForm.title = ''; lessonForm.summary = ''; await load() } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được bài học.' } } onMounted(load)
</script>
